#include <bits/stdc++.h>
using namespace std;using C=vector<int>;using Clock=chrono::steady_clock;using U=uint64_t;
struct Stop{};struct Node{int v,l,h;};struct Key{int v,l,h;bool operator==(const Key&x)const{return v==x.v&&l==x.l&&h==x.h;}};
struct Hash{size_t operator()(const Key&x)const{return (U(x.v)*0x9e3779b97f4a7c15ULL)^(U(x.l)*0xbf58476d1ce4e5b9ULL)^(U(x.h)*0x94d049bb133111ebULL);}};
struct Solver{
 int n=0;vector<C> cs;vector<int> order,rank,trace,joined,solution;vector<Node> nodes={{INT_MAX,0,0},{INT_MAX,1,1}};unordered_map<Key,int,Hash> unique;unordered_map<U,int> memo;Clock::time_point end;size_t maxnodes=850000;U ops=0,peakmemo=0;string reason="none";int widest=0;long long joins=0;
 void guard(){if(Clock::now()>=end){reason="deadline";throw Stop{};}if(nodes.size()>=maxnodes||memo.size()>2500000){reason="node_budget";throw Stop{};}}
 void tick(){if((++ops&1023)==0)guard();}
 bool read(const string&f){ifstream in(f);string line;C c;long long m=-1,got=0;while(getline(in,line)){tick();istringstream s(line);string t;s>>t;if(t.empty()||t=="c")continue;if(t=="%")break;if(t=="p"){string fmt;if(m!=-1||!(s>>fmt>>n>>m)||fmt!="cnf"||n<0||m<0)return false;if(n>1000||m>30000){reason="input_budget";throw Stop{};}continue;}s.clear();s.str(line);long long l;while(s>>l){if(m<0||l>n||l< -n)return false;if(!l){++got;sort(c.begin(),c.end());c.erase(std::unique(c.begin(),c.end()),c.end());bool taut=false;for(int a:c)if(binary_search(c.begin(),c.end(),-a)){taut=true;break;}if(!taut)cs.push_back(c);c.clear();}else c.push_back((int)l);}}return m>=0&&got==m&&c.empty();}
 int mk(int v,int l,int h){if(l==h)return l;tick();Key k{v,l,h};auto i=unique.find(k);if(i!=unique.end())return i->second;if(nodes.size()>=maxnodes){reason="node_budget";throw Stop{};}int id=nodes.size();nodes.push_back({v,l,h});unique.emplace(k,id);return id;}
 int apply(int a,int b,bool disj){tick();if(a==b)return a;if(a>b)swap(a,b);if(disj){if(a==0)return b;if(a==1)return 1;}else{if(a==0)return 0;if(a==1)return b;}U k=(U(a)<<32)|U(b);if(disj)k|=1ULL<<63;auto it=memo.find(k);if(it!=memo.end())return it->second;Node x=nodes[a],y=nodes[b];int v=min(x.v,y.v);int l=apply(x.v==v?x.l:a,y.v==v?y.l:b,disj),h=apply(x.v==v?x.h:a,y.v==v?y.h:b,disj);int z=mk(v,l,h);memo.emplace(k,z);peakmemo=max(peakmemo,(U)memo.size());return z;}
 void ordering(bool adaptive){vector<set<int>> adj(n+1);vector<bool> alive(n+1,true);for(auto&c:cs){for(int l:c)for(int k:c){tick();if(abs(l)!=abs(k))adj[abs(l)].insert(abs(k));}}rank.assign(n+1,-1);for(int step=0;step<n;step++){guard();int best=-1;tuple<long long,int,int> key{LLONG_MAX,INT_MAX,INT_MAX};for(int v=1;v<=n;v++)if(alive[v]){tick();if(!adaptive){best=v;break;}int d=adj[v].size();long long missing=0;if(n<=180&&d<=80){for(int a:adj[v])for(int b:adj[v]){tick();if(a<b&&!adj[a].count(b))missing++;}}else missing=(long long)d*d;auto k=make_tuple(missing,d,v);if(k<key){key=k;best=v;}}rank[best]=step;order.push_back(best);widest=max(widest,(int)adj[best].size());vector<int> nb(adj[best].begin(),adj[best].end());for(int a:nb){adj[a].erase(best);for(int b:nb)if(a!=b){tick();adj[a].insert(b);}}adj[best].clear();alive[best]=false;}}
 int clause(C c){sort(c.begin(),c.end(),[&](int a,int b){return rank[abs(a)]>rank[abs(b)];});int f=0;for(int l:c)f=l>0?mk(rank[l],f,1):mk(rank[-l],1,f);return f;}
 bool eval(int id,const vector<int>&a){while(id>1){tick();auto p=nodes[id];id=a[order[p.v]]?p.h:p.l;}return id==1;}
 bool good(const vector<int>&a){for(auto&c:cs){bool sat=false;for(int l:c)if(a[abs(l)]==(l>0)){sat=true;break;}if(!sat)return false;}return true;}
 void cert(const string&out){if(out.empty())return;ofstream f(out);f<<"symbolic-elimination-v1\n";for(int v:order)f<<v<<' ';f<<"0\n";if(!f)throw runtime_error("cert write");}
 int solve(const string&out,bool adaptive){if(order.empty())ordering(adaptive);vector<vector<int>> buckets(n);joined.assign(n,1);for(auto&c:cs){int f=clause(c);if(f==0){cert(out);return 20;}if(f>1)buckets[nodes[f].v].push_back(f);}for(int v=0;v<n;v++){guard();memo.clear();auto& b=buckets[v];if(b.empty())continue;sort(b.begin(),b.end());b.erase(std::unique(b.begin(),b.end()),b.end()); // balanced pairwise factor conjunction
 while(b.size()>1){vector<int> next;for(size_t i=0;i<b.size();i+=2){int f=i+1<b.size()?apply(b[i],b[i+1],false):b[i];joins++;if(f==0){cert(out);return 20;}if(f!=1)next.push_back(f);}if(next.empty())next.push_back(1);b=move(next);}int f=b[0];joined[v]=f;int projected=f;if(f>1&&nodes[f].v==v){Node p=nodes[f];projected=apply(p.l,p.h,true);}if(projected==0){cert(out);return 20;}if(projected>1){if(nodes[projected].v<=v)throw runtime_error("order invariant");buckets[nodes[projected].v].push_back(projected);}}
 vector<int>a(n+1);for(int v=n-1;v>=0;v--){a[order[v]]=0;if(!eval(joined[v],a)){a[order[v]]=1;if(!eval(joined[v],a))throw runtime_error("lift invariant");}}if(!good(a))throw runtime_error("source model invariant");solution=a;if(out.empty())return 10;ofstream f(out);f<<"v ";for(int i=1;i<=n;i++)f<<(a[i]?i:-i)<<' ';f<<"0\n";if(!f)throw runtime_error("model write");return 10;}
};
